target.css:
:root {
  --ink: #20342e;
  --muted: #63746d;
  --paper: #fffdf6;
  --line: #d9ddd0;
  --moss: #426d55;
  --moss-pale: #e5f0e5;
  --sun: #d99a3d;
}

.flight-card {
  box-sizing: border-box;
  width: 480px;
  padding: 18px 20px 16px;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.card-header,
.bird-row,
.card-footer {
  display: flex;
  align-items: center;
}

.card-header {
  justify-content: space-between;
}

.eyebrow,
.label,
.route,
.card-footer p {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

h1,
h2 {
  margin: 0;
}

h1 {
  margin-top: 5px;
  font-size: 22px;
  line-height: 1.1;
}

.status {
  padding: 6px 10px;
  color: var(--moss);
  background: var(--moss-pale);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
}

.bird-row {
  gap: 12px;
  margin: 16px 0;
  padding: 12px;
  background: var(--moss-pale);
  border-radius: 12px;
}

.bird-mark {
  display: grid;
  width: 42px;
  height: 42px;
  margin: 0;
  place-items: center;
  background: var(--paper);
  border-radius: 50%;
  font-size: 23px;
}

.bird-copy {
  flex: 1;
}

h2 {
  margin: 3px 0 4px;
  font-size: 16px;
  line-height: 1.1;
}

h2 span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 500;
}

.route {
  color: var(--moss);
  font-size: 10px;
}

.details {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  border: 1px solid var(--line);
  border-radius: 10px;
}

.detail-item {
  padding: 10px 12px;
}

.detail-item + .detail-item {
  border-left: 1px solid var(--line);
}

.detail-item strong {
  display: block;
  margin-top: 5px;
  font-size: 14px;
  line-height: 1;
}

.card-footer {
  justify-content: space-between;
  margin-top: 14px;
}

.card-footer p {
  font-size: 10px;
}

button {
  padding: 0;
  color: var(--moss);
  background: transparent;
  border: 0;
  font-size: 12px;
  font-weight: 700;
}

button span {
  margin-left: 4px;
  color: var(--sun);
  font-size: 16px;
}

